CREATE TABLE "AudioQueue" ("guildId" TEXT PRIMARY KEY, "items" JSONB NOT NULL DEFAULT '[]', "state" TEXT NOT NULL DEFAULT 'IDLE', "loop" BOOLEAN NOT NULL DEFAULT false, "shuffle" BOOLEAN NOT NULL DEFAULT false, "claimId" TEXT, "leaseUntil" TIMESTAMP(3), "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AudioQueue_state_check" CHECK ("state" IN ('IDLE','STARTING','PLAYING','INTERRUPTED')), CONSTRAINT "AudioQueue_items_check" CHECK (jsonb_typeof("items") = 'array' AND jsonb_array_length("items") <= 50));
CREATE TABLE "AudioPlaylist" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "name" TEXT NOT NULL, "items" JSONB NOT NULL, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AudioPlaylist_items_check" CHECK (jsonb_typeof("items") = 'array' AND jsonb_array_length("items") <= 50));
CREATE UNIQUE INDEX "AudioPlaylist_guildId_name_key" ON "AudioPlaylist"("guildId","name");
CREATE INDEX "AudioPlaylist_guildId_createdAt_idx" ON "AudioPlaylist"("guildId","createdAt");
